mapper.select:
SELECT a.*, sum( b.total_num ) AS alarmNumber FROM medical_device_statistics a left JOIN medical_alarm_statistics b ON a.device_prod_category_code = b.device_prod_category_code AND a.acquisition_date = b.acquisition_date and a.tenant=b.tenant
a.tenant = #{param.tenant}
and a.device_prod_category_code =#{param.deviceProdCategoryCode}
and a.create_time between #{param.period.begin} and #{param.period.end}
group by tenant,device_prod_category_code
